# NukeCraft fidelity oracle: generated by `nukecraft-cli fidelity export`. Do not edit.
#
# Run it inside Nuke (Non-commercial works). In the Script Editor:
#
#     exec(open('/path/to/nukecraft_fidelity.py').read())
#
# It builds each small synthetic test graph, samples pixel and knob values, records the default
# values of the knobs NukeCraft implements, deletes everything it built, and writes
# nukecraft_oracle.json next to this file (or to $NUKECRAFT_ORACLE_OUT, or your home folder).
#
# Written for Nuke Non-commercial's limits: every graph is tiny (64x64, a handful of nodes), nodes
# are kept by reference and never looked up (its Python API retrieves at most 10 nodes per script),
# and nothing is rendered to disk. The file it writes holds only numbers measured on these
# synthetic graphs.
import json
import os
import traceback

import nuke

CASES = json.loads(r'''__CASES__''')
DEFAULT_KNOBS = json.loads(r'''__DEFAULTS__''')


def _out_path():
    env = os.environ.get('NUKECRAFT_ORACLE_OUT')
    if env:
        return env
    try:
        here = os.path.dirname(os.path.abspath(__file__))
    except NameError:
        here = os.path.expanduser('~')
    return os.path.join(here, 'nukecraft_oracle.json')


def _set_root(width, height):
    name = 'nukecraft_fidelity_%dx%d' % (width, height)
    nuke.addFormat('%d %d 1.0 %s' % (width, height, name))
    root = nuke.root()
    root['format'].setValue(name)
    root['first_frame'].setValue(1)
    root['last_frame'].setValue(100)


def _set_knob(node, name, value):
    knob = node.knob(name)
    if knob is None:
        raise KeyError('%s has no knob %s' % (node.Class(), name))
    if isinstance(value, list):
        try:
            knob.setValue(value)
        except Exception:
            for i, v in enumerate(value):
                knob.setValue(v, i)
    else:
        knob.setValue(value)


def _set_key(node, name, frame, value):
    knob = node.knob(name)
    if knob is None:
        raise KeyError('%s has no knob %s' % (node.Class(), name))
    knob.setAnimated()
    if isinstance(value, list):
        for i, v in enumerate(value):
            knob.setValueAt(v, frame, i)
    else:
        knob.setValueAt(value, frame)


def _build(case, made, order):
    _set_root(case['width'], case['height'])
    for nd in case['nodes']:
        node = getattr(nuke.nodes, nd['class'])()
        made[nd['name']] = node
        order.append(node)
        for i, src in enumerate(nd.get('inputs') or []):
            if src is not None:
                node.setInput(i, made[src])
        for name, value in list(nd.get('knobs', {}).items()) + list(nd.get('nuke_knobs', {}).items()):
            _set_knob(node, name, value)
        for key in nd.get('keys', []):
            _set_key(node, key['knob'], key['frame'], key['value'])


def _measure(case, made, values):
    for s in case['samples']:
        node = made[s['node']]
        nuke.frame(s['frame'])
        for x, y in s['points']:
            for ch in s['channels']:
                # The centre of pixel (x, y): Nuke and NukeCraft both put pixel centres at +0.5.
                v = node.sample(ch, x + 0.5, y + 0.5)
                values['px:%s:%s:%d:%d:%s' % (s['node'], s['label'], x, y, ch)] = float(v)
    for ks in case['knob_samples']:
        knob = made[ks['node']].knob(ks['knob'])
        for frame, label in zip(ks['frames'], ks['labels']):
            for i in range(ks['components']):
                values['knob:%s:%s:%s:%d' % (ks['node'], ks['knob'], label, i)] = float(knob.getValueAt(frame, i))


def _knob_value(knob):
    try:
        size = knob.arraySize()
    except AttributeError:
        size = None
    if size is not None and size > 1:
        return [knob.value(i) for i in range(size)]
    v = knob.value()
    if isinstance(v, (bool, int, float)) or v is None:
        return v
    return str(v)


def _defaults():
    out = {}
    for cls, names in sorted(DEFAULT_KNOBS.items()):
        try:
            node = getattr(nuke.nodes, cls)()
        except Exception as e:
            out[cls] = {'error': str(e)}
            continue
        try:
            entry = {}
            for name in names:
                knob = node.knob(name)
                if knob is not None:
                    try:
                        entry[name] = _knob_value(knob)
                    except Exception as e:
                        entry[name] = 'error: %s' % e
            out[cls] = entry
        finally:
            nuke.delete(node)
    return out


def run():
    try:
        nc = bool(nuke.env.get('nc', False))
    except Exception:
        nc = None
    result = {
        'generator': 'nukecraft-fidelity/1',
        'nuke': {'version': getattr(nuke, 'NUKE_VERSION_STRING', 'unknown'), 'nc': nc},
        'cases': {},
        'defaults': {},
    }
    start_frame = nuke.frame()
    for case in CASES:
        made, order = {}, []
        entry = {'values': {}, 'error': None}
        try:
            _build(case, made, order)
            _measure(case, made, entry['values'])
        except Exception:
            entry['error'] = traceback.format_exc(limit=4)
        finally:
            for node in reversed(order):
                try:
                    nuke.delete(node)
                except Exception:
                    pass
        result['cases'][case['id']] = entry
    _set_root(64, 64)
    result['defaults'] = _defaults()
    nuke.frame(start_frame)
    path = _out_path()
    with open(path, 'w') as f:
        json.dump(result, f, indent=1, sort_keys=True)
    failed = sum(1 for c in result['cases'].values() if c['error'])
    print('NukeCraft fidelity: %d cases (%d with errors) written to %s' % (len(result['cases']), failed, path))
    return path


run()
